using System;using System.IO;using System.Collections.Generic;using System.Diagnostics;using System.Xml.Serialization;
namespace EanEtikety {
public sealed class UpdateInstall {public string Directory,PackageId;}
[XmlRoot("LabelDesignerActivation")]public sealed class UpdateState {public int Format=1;public string Family,BackupDirectory;public UpdateInstall Current,Previous;public List<string> AuthorizedRoots=new List<string>();}
public sealed class UpdateActivation {
 public readonly string Root,PackagesRoot,StatePath,Family,Preferences;
 public UpdateActivation(string root,string family,string preferences){if(!UpdateFiles.FamilyValid(family))throw new ArgumentException("family");Root=Path.GetFullPath(root);Family=family;Preferences=preferences;PackagesRoot=Path.Combine(Root,"packages");StatePath=Path.Combine(Root,"activation.xml");}
 public static UpdateActivation Default(){return new UpdateActivation(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"NDLabelMaker","Updates",UpdateFiles.CurrentFamily),UpdateFiles.CurrentFamily,StartupStore.DefaultPath);}
 public static bool SamePath(string a,string b){return !string.IsNullOrEmpty(a)&&!string.IsNullOrEmpty(b)&&string.Equals(Path.GetFullPath(a).TrimEnd('\\','/'),Path.GetFullPath(b).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase);}
 public UpdatePackage Installed(string directory){var p=UpdatePackage.Read(Path.Combine(directory,"package-manifest.xml"));if(p.Family!=Family)throw new InvalidDataException("Wrong installation platform.");bool managed=Path.GetFullPath(directory).StartsWith(Path.GetFullPath(PackagesRoot).TrimEnd((char)92,(char)47)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);p.VerifyDirectory(directory,!managed);return p;}
 public UpdateState State(){try{if(!File.Exists(StatePath))return new UpdateState{Family=Family};var s=UpdateFiles.ReadXml<UpdateState>(StatePath,128*1024);ValidateState(s);return s;}catch{if(!File.Exists(StatePath+".bak"))throw;var s=UpdateFiles.ReadXml<UpdateState>(StatePath+".bak",128*1024);ValidateState(s);return s;}}
 void ValidateState(UpdateState s){if(s==null||s.Format!=1||s.Family!=Family||s.AuthorizedRoots==null||s.AuthorizedRoots.Count>64)throw new InvalidDataException("Invalid activation state.");foreach(var root in s.AuthorizedRoots)if(string.IsNullOrEmpty(root)||!Path.IsPathRooted(root))throw new InvalidDataException("Invalid activation root.");foreach(var item in new[]{s.Current,s.Previous})if(item!=null&&(!Path.IsPathRooted(item.Directory??"")||!UpdateFiles.Hex(item.PackageId,64)||!s.AuthorizedRoots.Exists(r=>SamePath(r,item.Directory))))throw new InvalidDataException("Invalid activation target.");}
 void Save(UpdateState state){while(state.AuthorizedRoots.Count>64){int index=state.AuthorizedRoots.FindIndex(r=>(state.Current==null||!SamePath(r,state.Current.Directory))&&(state.Previous==null||!SamePath(r,state.Previous.Directory))&&r.StartsWith(PackagesRoot+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase));if(index<0)index=state.AuthorizedRoots.FindIndex(r=>(state.Current==null||!SamePath(r,state.Current.Directory))&&(state.Previous==null||!SamePath(r,state.Previous.Directory)));if(index<0)throw new InvalidDataException("Cannot bound activation history.");state.AuthorizedRoots.RemoveAt(index);}ValidateState(state);ProjectXml.Save(StatePath,state,StatePath+".bak");}
 UpdateInstall Entry(string directory){var p=Installed(directory);return new UpdateInstall{Directory=Path.GetFullPath(directory),PackageId=p.PackageId};}
 void Restore(UpdateState state){ValidateState(state);ProjectXml.Save(StatePath,state);ProjectXml.Save(StatePath+".bak",state);}
 string Backup(){string backups=Path.Combine(Root,"settings-backups");Directory.CreateDirectory(backups);UpdateFiles.NoReparse(backups);string pending=Path.Combine(backups,".pending-"+Guid.NewGuid().ToString("N")),target=Path.Combine(backups,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(pending);long bytes=0;int count=0;
  try{Action<string,string> copy=(source,name)=>{if(!File.Exists(source))return;UpdateFiles.NoReparse(source);bytes+=new FileInfo(source).Length;if(++count>4096||bytes>512L*1024*1024)throw new IOException("Settings backup limit exceeded.");string dest=UpdateFiles.Child(pending,name);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(source,dest,false);};copy(Preferences,"startup.xml");copy(Preferences+".layout","startup.xml.layout");string workspace=Preferences+".workspace";if(Directory.Exists(workspace)){UpdateFiles.NoReparse(workspace);var todo=new Stack<string>();todo.Push(workspace);while(todo.Count>0){string dir=todo.Pop();UpdateFiles.NoReparse(dir);foreach(var file in Directory.GetFiles(dir))if(!file.EndsWith(".lock",StringComparison.OrdinalIgnoreCase)&&!file.EndsWith(".recovery.xml",StringComparison.OrdinalIgnoreCase))copy(file,"workspace/"+file.Substring(workspace.Length+1).Replace('\\','/'));foreach(var sub in Directory.GetDirectories(dir))todo.Push(sub);}}Directory.Move(pending,target);return target;}finally{if(Directory.Exists(pending))UpdateFiles.DeletePending(backups,pending);}
 }
 public void Activate(string runningDirectory,string candidateDirectory,Func<string,bool> launch){Directory.CreateDirectory(Root);UpdateFiles.NoReparse(Root);using(var lease=new FileStream(Path.Combine(Root,"activation.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
  var current=Entry(runningDirectory);var candidate=Entry(candidateDirectory);string allowed=Path.GetFullPath(PackagesRoot).TrimEnd('\\','/')+Path.DirectorySeparatorChar;if(!candidate.Directory.StartsWith(allowed,StringComparison.OrdinalIgnoreCase)||Path.GetFileName(candidate.Directory)!=candidate.PackageId)throw new InvalidDataException("Update was not prepared in the managed store.");if(current.PackageId==candidate.PackageId)throw new InvalidOperationException(Loc.T("Táto zostava je už pripravená."));
  var old=State();var next=ProjectXml.Decode<UpdateState>(ProjectXml.Encode(old));foreach(var path in new[]{current.Directory,candidate.Directory})if(!next.AuthorizedRoots.Exists(r=>SamePath(r,path)))next.AuthorizedRoots.Add(path);next.Previous=current;next.Current=candidate;next.BackupDirectory=Backup();Save(next);
  try{if(!launch(Path.Combine(candidate.Directory,"ND-LabelDesigner.exe")))throw new IOException(Loc.T("Novú verziu sa nepodarilo spustiť."));}catch{Restore(old);throw;}
 }}
 public void Rollback(string runningDirectory,Func<string,bool> launch){Directory.CreateDirectory(Root);using(var lease=new FileStream(Path.Combine(Root,"activation.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var old=State();if(old.Current==null||old.Previous==null||!old.AuthorizedRoots.Exists(r=>SamePath(r,runningDirectory)))throw new InvalidOperationException(Loc.T("Predchádzajúca verzia nie je dostupná."));var previous=Entry(old.Previous.Directory);if(previous.PackageId!=old.Previous.PackageId)throw new InvalidDataException("Previous package identity changed.");var next=ProjectXml.Decode<UpdateState>(ProjectXml.Encode(old));next.Previous=old.Current;next.Current=old.Previous;Save(next);try{if(!launch(Path.Combine(previous.Directory,"ND-LabelDesigner.exe")))throw new IOException(Loc.T("Predchádzajúcu verziu sa nepodarilo spustiť."));}catch{Restore(old);throw;}}}
 public string RedirectTarget(string runningDirectory){var state=State();if(state.Current==null||SamePath(state.Current.Directory,runningDirectory)||!state.AuthorizedRoots.Exists(r=>SamePath(r,runningDirectory)))return null;var p=Installed(state.Current.Directory);if(p.PackageId!=state.Current.PackageId)throw new InvalidDataException("Active package identity changed.");return Path.Combine(state.Current.Directory,"ND-LabelDesigner.exe");}
 public static bool Launch(string exe){using(var process=Process.Start(new ProcessStartInfo{FileName=exe,WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false}))return process!=null;}
 public static bool TryStartupRedirect(){try{string target=Default().RedirectTarget(AppDomain.CurrentDomain.BaseDirectory);return target!=null&&Launch(target);}catch{return false;}}
}
}
